<script>
const tabData = {
  "M-BTM": {
    group: "mouse",
    title: "M–BTM",
    description: "Our universal Innocage® mouse cage bottom fits all Innocage® mouse cage lids, feeders, and watering solutions. Mouse cage bottoms arrive empty or pre-bedded.",
    imageSrc: "https://innovive.com/wp-content/uploads/2026/06/M-BTM.png",
    advantages: [
      "Bottoms nest densely in stacks of 25",
      "Flexible, standardized, research-ready caging",
      "Patented lightweight caging",
      "14–day cage changes",
      "Completely disposable end-to-end solution",
      "Closed-loop recycling services available"
    ]
  },
  "R-BTM-H": {
    group: "rat",
    title: "R–BTM–H",
    description: "Standard disposable rat cage bottom arrives irradiated and ready for use. Made of 100% PET plastic. BPA-free.",
    imageSrc: "https://innovive.com/wp-content/uploads/2026/06/R-BTM-H.png",
    advantages: [
      "Flexible, standardized, research-ready caging",
      "Patented lightweight caging",
      "14–day cage changes",
      "Completely disposable end-to-end solution",
      "Closed-loop recycling services available"
    ]
  },
  "R-BTM-XL": {
    group: "rat",
    title: "R–BTM–XL",
    description: "XL rat cage sized for larger rats and breeding. Made from 100% PET and BPA-free plastic. The bottom arrives irradiated and ready for use.",
    imageSrc: "https://innovive.com/wp-content/uploads/2026/06/R-BTM-XL.png",
    advantages: [
      "Flexible, standardized, research-ready caging",
      "Patented lightweight caging",
      "14–day cage changes",
      "Completely disposable end-to-end solution",
      "Closed-loop recycling services available"
    ]
  }
};

const mainTabs = document.querySelectorAll('.rcl-cat-tab');
const tabs = document.querySelectorAll('.rcl-prod-tab');
const dynamicContentArea = document.getElementById('dynamic-content-area');
const advantagesArea = document.getElementById('advantages-area');
const titleEl = document.getElementById('dynamic-title');
const descriptionEl = document.getElementById('dynamic-description');
const advantagesListEl = document.getElementById('dynamic-advantages');
const imageEl = document.getElementById('dynamic-image');

let currentGroup = 'rat';

function showGroupTabs(group) {
  tabs.forEach(t => {
    if (t.getAttribute('data-group') === group) {
      t.style.display = '';
    } else {
      t.style.display = 'none';
      t.classList.remove('active');
    }
  });

  const firstTab = document.querySelector(
    '.rcl-prod-tab[data-group="' + group + '"]'
  );
    if (
    firstTab &&
    !document.querySelector(
      '.rcl-prod-tab[data-group="' + group + '"].active'
    )
  ) {
    firstTab.classList.add('active');
    updateContent(firstTab.getAttribute('data-id'));
  }
}

function updateContent(tabId) {
  const data = tabData[tabId];
  if (!data) return;

  dynamicContentArea.style.opacity = 0;
  advantagesArea.style.opacity = 0;
  imageEl.style.opacity = 0;

  setTimeout(() => {
    titleEl.textContent = data.title;
    descriptionEl.textContent = data.description;

    advantagesListEl.innerHTML = '';

    data.advantages.forEach(adv => {
      const li = document.createElement('li');
      li.textContent = adv;
      advantagesListEl.appendChild(li);
    });

    dynamicContentArea.style.opacity = 1;
    advantagesArea.style.opacity = 1;

    const defaultImg =
      'https://images.unsplash.com/photo-1581093458791-9f3c3900df4b?auto=format&fit=crop&w=600&q=80';

    imageEl.src = data.imageSrc || defaultImg;

    imageEl.onload = () => {
      imageEl.style.opacity = 1;
    };

    imageEl.onerror = () => {
      if (imageEl.src !== defaultImg) {
        imageEl.src = defaultImg;
      }
      imageEl.style.opacity = 1;
    };
  }, 250);
}

// Main tab click (Mouse / Rat)
mainTabs.forEach(mt => {
  mt.addEventListener('click', () => {
    if (mt.classList.contains('active')) return;

    mainTabs.forEach(m => m.classList.remove('active'));
    mt.classList.add('active');

    currentGroup = mt.getAttribute('data-group');

    tabs.forEach(t => t.classList.remove('active'));
    showGroupTabs(currentGroup);
  });
});

// Sub tab click
tabs.forEach(tab => {
  tab.addEventListener('click', () => {
    if (tab.classList.contains('active')) return;

    tabs.forEach(t => {
      if (t.getAttribute('data-group') === currentGroup) {
        t.classList.remove('active');
      }
    });

    tab.classList.add('active');
    updateContent(tab.getAttribute('data-id'));
  });
});

// Initialize
showGroupTabs('rat');
updateContent('R-BTM-H');
// URL parameter based tab opening
document.addEventListener("DOMContentLoaded", function () {

  const params = new URLSearchParams(window.location.search);
  const targetTab = params.get("tab");

  if (!targetTab) return;

  const tab = document.querySelector(
    '.rcl-prod-tab[data-id="' + targetTab + '"]'
  );

  if (tab) {

    tabs.forEach(t => {
      if (t.getAttribute('data-group') === 'rat') {
        t.classList.remove('active');
      }
    });

    tab.classList.add('active');

    currentGroup = 'rat';

    updateContent(targetTab);
  }

});
</script>
<style>#specs-rbtmxl{display:none}</style>
<script>
(function(){
  function sync(id){
    var h=document.getElementById('specs-rbtmh'),xl=document.getElementById('specs-rbtmxl');
    if(!h||!xl)return;
    var xlOn=(id==='R-BTM-XL');
    xl.style.display=xlOn?'flex':'none';
    h.style.display=xlOn?'none':'flex';
  }
  function init(){
    document.querySelectorAll('.rcl-prod-tab').forEach(function(b){
      b.addEventListener('click',function(){sync(b.getAttribute('data-id'));});
    });
  }
  if(document.readyState!=='loading')init();else document.addEventListener('DOMContentLoaded',init);
})();
</script>
","custom_css":"@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

.rcl-widget {
  background: transparent;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 24px;
  width: 100%;
  max-width: 1400px;
  box-sizing: border-box;
}

.rcl-image-col {
  flex: 0 0 42%;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 30px;
  min-height: 420px;
  border-radius: 12px;
  /*box-shadow: 0px 20px 40px 0px #0F1D280F;*/
  box-sizing: border-box;
}

.rcl-image-col img {
  width: 100%;
  max-width: 340px;
  height: auto;
  object-fit: contain;
  transition: opacity 0.35s ease;
  display: block;
}

.rcl-tabs-col {
  flex: 1 1 58%;
  padding: 44px 48px 44px 40px;
  display: flex;
  flex-direction: column;
  gap: 0;
  box-sizing: border-box;
}

.rcl-cat-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1.5px solid #d9dde3;
  margin-bottom: 20px;
}

.rcl-cat-tab {
  background: none;
  border: none;
  outline: none;
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  color: #333333;
  padding: 10px 28px 10px 0;
  position: relative;
  transition: color 0.2s;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.rcl-cat-tab:first-child { padding-left: 0; }

.rcl-cat-tab::after {
  content: '';
  position: absolute;
  bottom: -1.5px;
  left: 0;
  right: 18px;
  height: 2px;
  background: #005287;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}
.rcl-cat-tab:hover {
  background: #fff;
  color: #005287;
}
.rcl-cat-tab.active {
  background: #FFF;
  color: #005287;
  font-weight: 700;
}

.rcl-cat-tab.active::after {
  transform: scaleX(1);
}

.rcl-prod-tabs {
  display: none;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}

.rcl-prod-tabs.active { display: flex; }

.rcl-prod-tab {
  background: #FFFFFF;
  border: 1.5px solid rgba(0, 82, 135, 0.2);
  border-radius: 6px;
  outline: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: #333333;
  padding: 8px 20px;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
  letter-spacing: 0.01em;
}

.rcl-prod-tab:hover {
  border-color: #005287;
  color: #FFF;
  background-color: #005287 !important;
}

.rcl-prod-tab.active {
  background: #005287;
  border-color: #005287;
  color: #FFFFFF;
}

.rcl-panel {
  display: none;
  flex-direction: column;
  gap: 6px;
  animation: rclFadeIn 0.25s ease;
}

.rcl-panel.active { display: flex; }

@keyframes rclFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}


.rcl-product-name {
  font-size: 40px;
  font-weight: 800;
  color: #00223D!important;
  line-height: 1.1;
  margin: 0 0 10px;
}

.rcl-product-desc {
  font-size: 14.5px;
  color: #666666;
  line-height: 1.65;
  margin: 0 0 14px;
}

.rcl-advantages-title {
  font-size: 15px;
  font-weight: 700;
  color: #00223D;
  margin: 0 0 8px;
}

.rcl-advantages-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rcl-advantages-list li {
  font-size: 14px;
  color: #666666;
  padding-left: 18px;
  position: relative;
  line-height: 1.55;
}

.rcl-advantages-list li::before {
